import {profiles,classify,orderedFiles,reviewPrompt,getLayers,fileLayer} from './core.mjs';
import {getDemo} from './demo.mjs';
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let saved={};try{saved=JSON.parse(localStorage.getItem('trace-v2')||'{}')}catch{}
let state={theme:'dark',mode:'files',profile:'backend',reviews:{},...saved};
if(!profiles[state.profile])state.profile='backend';
state.stacks??={backend:'nestjs',frontend:'react',mobile:'android'}; state.patterns??={backend:'layered',frontend:'feature',mobile:'mvvm'};
const options=()=>({stack:state.stacks[state.profile],pattern:state.patterns[state.profile]});
const layers=()=>getLayers(state.profile,options().pattern,options().stack);
let session=null,query='',activePath='',editor=null,editId=null,jobTimer=null;
const key=()=>session?`${session.repo}:${session.revision}`:`demo-v3:${state.profile}:${options().stack}`;
const review=()=>state.reviews[key()]??=( {comments:[],done:[],overrides:{},drafts:{},instruction:''} );
const files=()=>session?session.files:getDemo(state.profile,options().stack);
function persist(){try{localStorage.setItem('trace-v2',JSON.stringify(state))}catch{toast('Could not save locally. Export your review.')}}
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4000)}
function applyTheme(){document.documentElement.dataset.theme=state.theme;$('#theme').textContent=state.theme==='dark'?'☀':'☾';$('#theme').setAttribute('aria-label',state.theme==='dark'?'Switch to light theme':'Switch to dark theme')}
function layer(f){return fileLayer(f,state.profile,review().overrides,options())}
function lineKey(path,index){return `${path}:${index}`}
function tree(){
 const root=Object.create(null);for(const f of files().filter(f=>f.path.toLowerCase().includes(query))){let node=root;const parts=f.path.split('/');parts.forEach((p,i)=>{if(i===parts.length-1)node[p]=f;else node=node[p]??=Object.create(null)})}
 function branch(node){return Object.entries(node).sort(([a],[b])=>a.localeCompare(b)).map(([name,value])=>typeof value.path==='string'?`<button class="file-link ${value.path===activePath?'active':''}" data-file="${esc(value.id)}" title="${esc(value.path)}"><span>⌘</span><span class="name">${esc(name)}</span><span class="status">${review().done.includes(value.path)?'✓':'M'}</span></button>`:`<details open><summary>${esc(name)}</summary><div>${branch(value)}</div></details>`).join('')}
 $('#tree').innerHTML=branch(root)||'<p>No matching files</p>';$('#file-count').textContent=files().length;
}
function thread(c){return `<div class="thread ${c.resolved?'resolved':''}"><div class="thread-head"><span class="avatar">YOU</span><span>${c.side==='old'?'Deleted line':'Line'} ${c.line} · ${c.resolved?'Resolved':'Comment'}</span><span class="spacer"></span><button data-edit="${c.id}">Edit</button><button data-resolve="${c.id}">${c.resolved?'Reopen':'Resolved ✓'}</button><button data-delete="${c.id}" aria-label="Delete comment">×</button></div><p>${esc(c.body)}</p></div>`}
function composer(f,index){const draftKey=lineKey(f.path,index);const line=f.lines[index];return `<form class="composer" data-editor-file="${esc(f.id)}" data-index="${index}"><label for="comment-body">${esc(f.path)} · ${line.kind==='del'?'deleted line':'line'} ${line.new??line.old}</label><textarea id="comment-body" required maxlength="10000" placeholder="Describe what should change…">${esc(review().drafts[draftKey]||'')}</textarea><div class="actions"><button type="button" data-cancel>Cancel</button><button class="primary" type="submit">${editId?'Save':'Add to review'}</button></div></form>`}
function fileCard(f){const r=review(),adds=f.lines.filter(l=>l.kind==='add').length,dels=f.lines.filter(l=>l.kind==='del').length;
return `<article class="file-card" id="${esc(f.id)}"><div class="file-header"><span class="path">⌘ ${esc(f.path)}</span><span class="stats"><span class="plus">+${adds}</span> <span class="minus">−${dels}</span></span><div class="spacer"></div>${state.mode==='route'?`<select data-layer="${esc(f.id)}" aria-label="Layer ${esc(f.path)}">${[...layers(),'Other changes'].map(l=>`<option ${l===layer(f)?'selected':''}>${esc(l)}</option>`).join('')}</select>`:''}<label><input type="checkbox" data-viewed="${esc(f.id)}" ${r.done.includes(f.path)?'checked':''}>Viewed</label></div><div class="diff">${f.lines.map((l,i)=>l.kind==='hunk'?`<div class="hunk">${esc(l.text)}</div>`:`<div class="line ${l.kind}" id="${esc(f.id)}-line-${i}"><button class="comment-trigger" data-comment="${esc(f.id)}" data-index="${i}" aria-label="Comment on ${esc(f.path)} ${l.kind==='del'?'old':'new'} line ${l.new??l.old}">+</button><span class="ln">${l.old??''}</span><span class="ln">${l.new??''}</span><span class="sign">${l.kind==='add'?'+':l.kind==='del'?'−':' '}</span><code>${esc(l.text)}</code></div>${r.comments.filter(c=>c.path===f.path&&c.index===i).map(thread).join('')}${editor===lineKey(f.path,i)?composer(f,i):''}`).join('')}</div></article>`}
function renderFeed(){const list=orderedFiles(files().filter(f=>f.path.toLowerCase().includes(query)),state.profile,state.mode,review().overrides,options());let last='',section=0,links=[];
 $('#feed').innerHTML=list.map(f=>{let head='';if(state.mode==='route'&&layer(f)!==last){last=layer(f);section++;links.push({label:last,id:`layer-${section}`});head=`<div class="layer-heading" id="layer-${section}"><b>${section}</b><h2>${esc(last)}</h2><span>${list.filter(x=>layer(x)===last).length} ${list.filter(x=>layer(x)===last).length===1?'file':'files'}</span></div>`}return head+fileCard(f)}).join('')||'<div class="empty">No changes to display</div>';
 $('#route-links').innerHTML=links.map(l=>`<a href="#${l.id}">${esc(l.label)}</a>`).join('<span>→</span>');$('#summary').textContent=`${list.length} files · +${list.flatMap(f=>f.lines).filter(l=>l.kind==='add').length} −${list.flatMap(f=>f.lines).filter(l=>l.kind==='del').length}`;
}
function counts(){$('#review-count').textContent=review().comments.filter(c=>!c.resolved).length;$('#progress').textContent=`Viewed ${review().done.length} of ${files().length} files`;$('#progress-bar').style.width=(files().length?review().done.length/files().length*100:0)+'%'}
function render(){applyTheme();$('#stack').innerHTML=Object.entries(profiles[state.profile].stacks).map(([id,label])=>`<option value="${id}" ${id===options().stack?'selected':''}>${label}</option>`).join('');$('#pattern').innerHTML=Object.entries(profiles[state.profile].patterns).map(([id,label])=>`<option value="${id}" ${id===options().pattern?'selected':''}>${label}</option>`).join('');$('#profile').value=state.profile;$('#files-mode').setAttribute('aria-pressed',state.mode==='files');$('#route-mode').setAttribute('aria-pressed',state.mode==='route');$('#route-info').hidden=state.mode!=='route';tree();renderFeed();counts()}
function jump(id){const f=files().find(f=>f.id===id);if(!f)return;activePath=f.path;tree();document.getElementById(id)?.scrollIntoView({behavior:'smooth',block:'start'})}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
 if(b.dataset.file){jump(b.dataset.file)}
 if(b.dataset.comment){const f=files().find(f=>f.id===b.dataset.comment);editor=lineKey(f.path,+b.dataset.index);editId=null;renderFeed();$('#comment-body').focus()}
 if(b.hasAttribute('data-cancel')){editor=null;editId=null;renderFeed()}
 if(b.dataset.resolve){const c=review().comments.find(c=>c.id===b.dataset.resolve);c.resolved=!c.resolved;persist();renderFeed();counts()}
 if(b.dataset.delete){review().comments=review().comments.filter(c=>c.id!==b.dataset.delete);persist();renderFeed();counts()}
 if(b.dataset.edit){const c=review().comments.find(c=>c.id===b.dataset.edit);editor=lineKey(c.path,c.index);editId=c.id;review().drafts[editor]=c.body;renderFeed();$('#comment-body').focus()}
});
document.addEventListener('input',e=>{if(e.target.id==='comment-body'){review().drafts[editor]=e.target.value;persist()}});
document.addEventListener('submit',e=>{const form=e.target.closest('.composer');if(!form)return;e.preventDefault();const body=$('#comment-body').value.trim();if(!body)return;const f=files().find(f=>f.id===form.dataset.editorFile),index=+form.dataset.index,l=f.lines[index];if(editId)review().comments.find(c=>c.id===editId).body=body;else review().comments.push({id:crypto.randomUUID(),path:f.path,index,line:l.new??l.old,side:l.kind==='del'?'old':'new',code:l.text,body,resolved:false});delete review().drafts[editor];editor=null;editId=null;persist();renderFeed();counts();toast('Comment added to review')});
document.addEventListener('change',e=>{if(e.target.dataset.viewed){const path=files().find(f=>f.id===e.target.dataset.viewed).path;review().done=review().done.filter(p=>p!==path);if(e.target.checked)review().done.push(path);persist();tree();counts()}if(e.target.dataset.layer){const path=files().find(f=>f.id===e.target.dataset.layer).path;review().overrides[path]=e.target.value;persist();renderFeed()}});
$('#theme').onclick=()=>{state.theme=state.theme==='dark'?'light':'dark';persist();applyTheme()};
$('#search').oninput=e=>{query=e.target.value.toLowerCase();tree();renderFeed()};
for(const mode of ['files','route'])$('#'+mode+'-mode').onclick=()=>{state.mode=mode;persist();render()};
$('#profile').onchange=e=>{state.profile=e.target.value;editor=null;editId=null;activePath='';query='';$('#search').value='';persist();render()};
$('#stack').onchange=e=>{state.stacks[state.profile]=e.target.value;editor=null;editId=null;persist();render()};
$('#pattern').onchange=e=>{state.patterns[state.profile]=e.target.value;persist();render()};
function packet(){return {schemaVersion:1,repo:session?.repo||'demo/checkout-service',revision:session?.revision||`demo-${state.profile}-v2`,profile:state.profile,...options(),createdAt:new Date().toISOString(),comments:review().comments.filter(c=>!c.resolved),instruction:review().instruction||''}}
function prompt(){const p=packet();return reviewPrompt(p)+(p.instruction?`\n\nAdditional instructions:\n${p.instruction}`:'')}
$('#review').onclick=()=>{const p=packet();$('#agent-info').textContent=session?.agent?'Codex will run locally in this repository and apply the requested changes.':'No local agent connected. Copy the task to your agent chat or download the review file.';$('#handoff-help').textContent=session?'Only open comments from this revision are sent. Refresh the diff after the agent finishes.': 'For a real repository: node server.mjs --repo /path/to/project --agent codex. This demo uses sample diffs.';$('#review-list').innerHTML=p.comments.map(c=>`<div class="review-item"><code>${esc(c.path)}:${c.line} · ${c.side==='old'?'old':'new'} version</code><p>${esc(c.body)}</p></div>`).join('')||'<p>Add a comment using + beside a line of code.</p>';$('#instruction').value=review().instruction;$('#send').hidden=!session?.agent;$('#send').disabled=!p.comments.length||!!jobTimer;$('#copy-prompt').disabled=!p.comments.length;$('#download').disabled=!p.comments.length;$('#handoff').showModal()};
$('#instruction').oninput=e=>{review().instruction=e.target.value;persist()};$('#close-dialog').onclick=()=>$('#handoff').close();
$('#copy-prompt').onclick=async()=>{try{await navigator.clipboard.writeText(prompt());toast('Task copied — paste it into your agent chat')}catch{toast('Clipboard unavailable. Download the JSON task instead.')}};
$('#download').onclick=()=>{const p={...packet(),prompt:prompt()},url=URL.createObjectURL(new Blob([JSON.stringify(p,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='trace-review.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Review file prepared')};
$('#send').onclick=async()=>{if(!session?.agent)return;$('#send').disabled=true;$('#job-state').textContent='Sending task…';try{const res=await fetch('/api/reviews',{method:'POST',headers:{'Content-Type':'application/json','X-Trace-Token':session.token},body:JSON.stringify(packet())});const job=await res.json();if(!res.ok)throw new Error(job.error);$('#job-state').textContent='Codex is working…';jobTimer=setInterval(async()=>{try{const res=await fetch('/api/jobs/'+job.id);if(!res.ok)throw new Error('Could not retrieve job status');const j=await res.json();$('#job-state').textContent=j.status==='running'?'Codex is working…':j.status==='succeeded'?'Done. Refresh the diff and review the changes.\n\n'+j.output:'The agent task failed.\n'+j.output;if(j.status!=='running'){clearInterval(jobTimer);jobTimer=null;$('#send').disabled=false}}catch(err){clearInterval(jobTimer);jobTimer=null;$('#job-state').textContent=err.message;$('#send').disabled=false}},1500)}catch(err){$('#job-state').textContent=err.message;$('#send').disabled=false}};
async function loadSession(silent=false){try{const res=await fetch('/api/session');if(!res.ok)throw new Error('Local server unavailable');session=await res.json();$('#repo').textContent=session.repo;$('#source-badge').textContent='LOCAL';$('#branch').textContent=session.branch+' → '+session.base;$('#title').textContent='Changes in '+session.repo;$('#refresh').hidden=false;editor=null;render()}catch(err){if(!silent)toast(err.message)}}
$('#refresh').onclick=()=>loadSession();
render();if(['127.0.0.1','localhost'].includes(location.hostname))loadSession(true);
